@sonoro1234 I now tested with creating a synthdef beforehand, so it's just waiting for starting the synth process itself (PartConv needs to allocate some memory as far as I understand). The result is the same in my testing. Here's the code:

```supercollider
(
//CAREFUL! this will create LOUD DISTORTION
//modified example from PartConv helpfile
~fftsize = 2048;
~numSynths = 2;

~syncBetweenSynths = true; //works fine
// ~syncBetweenSynths = false; //THIS WILL CREATE LOUD DISTORTION

Server.supernova;
s.options.memSize_(2.pow(16)); //if there is not enough realtime memory allocated, PartConv will crash the server
s.options.hardwareBufferSize_(256);

s.waitForBoot {
	var ir, irbuffer, bufsize;
	ir = [1] ++ 0.dup(100) ++ (
		(1, 0.99998 .. 0)
		.collect {|f|
			f = f.squared.squared;
			f = if(f.coin) { 0 }{ f.squared };
			f = if(0.5.coin) { 0 - f } { f }
		} * 0.1
	);
	ir = ir.normalizeSum;
	irbuffer = Buffer.loadCollection(s, ir);
	s.sync;
	
	SynthDef(\pt_test, {arg playbuf = 0, irbuf = 0, amp = 0.5, out = 0;
		var sig;
		var input = PlayBuf.ar(1, playbuf, loop:1);
		sig = PartConv.ar(input, ~fftsize, irbuf, 0.5) * -6.dbamp;
		Out.ar(out, sig * amp);
	}).add;

	bufsize = PartConv.calcBufSize(~fftsize, irbuffer);
	~irspectrum = Buffer.alloc(s, bufsize, 1);
	~irspectrum.preparePartConv(irbuffer, ~fftsize);
	s.sync;

	irbuffer.free; // don't need time domain data anymore, just needed spectral version
	~buffer = Buffer.read(s, Platform.resourceDir +/+ "sounds/a11wlk01.wav");
	~target = ParGroup();
	s.sync;

	~allSynths = ~numSynths.collect({|inc|
		var synth = Synth(\pt_test, [\playbuf, ~buffer, \irbuf, ~irspectrum, \amp, -26.dbamp, \out, inc], ~target);
		if(~syncBetweenSynths, {s.sync});
		synth;
	});
}
)

//free everything
(
~target.free;
~buffer.free;
~irspectrum.free;
currentEnvironment.clear;
)
```
